    end

    with_env(AGENT_ID: "brew-test") do
      assert_match "RELEASED lib/**", shell_output("#{bin}/alock release lib --dir #{testpath}")
    end

    # Once released, it reads as free to anybody, and exits 0.
    with_env(AGENT_ID: "brew-test-other") do
